UPDATE pbh_books SET title='Between the Avalanche and the Ashes', author='Dorota Chioma', genres='["Memoir & Biography"]', image='https://static.wixstatic.com/media/60259a_c2e69e6b80d24ee39e89867de1a6888d~mv2.jpg', amazon='https://www.amazon.co.uk/dp/1036969312', feature='/books/between-the-avalanche-and-the-ashes.html', photo='/images/featured-authors/dorota-chioma.webp', tag='Memoir & Mental Health', hook='A visual artist navigates the extremes of bipolar disorder, discovering that creativity can be both a refuge and a risk.', description='Between the Avalanche and the Ashes is an intimate memoir of living with bipolar disorder, navigating emotional extremes and rediscovering oneself through creativity.

Through personal reflections, diary entries and artistic milestones, Dorota Chioma takes readers through the exhilarating intensity of mania, the devastating weight of depression and the uncertain territory between them.

Art becomes a central thread throughout her journey — sometimes a sanctuary, sometimes an expression of overwhelming energy, and sometimes the only language available when words fail.

Rather than presenting recovery as a straightforward journey, the book explores its complexity, contradictions and fragile moments of hope. It raises difficult questions about identity, creativity, illness and the cost of pursuing passion while protecting one’s wellbeing.

Ultimately, it is a testament to the courage of continuing, creating and finding meaning in the aftermath.', status='archive', sort_index='0' WHERE lower(title)=lower('Between the Avalanche and the Ashes');
INSERT INTO pbh_books(id,title,author,genres,image,amazon,feature,photo,tag,hook,description,status,sort_index) SELECT 'seed-avalanche-dorota','Between the Avalanche and the Ashes','Dorota Chioma','"[\"Memoir & Biography\"]"','https://static.wixstatic.com/media/60259a_c2e69e6b80d24ee39e89867de1a6888d~mv2.jpg','https://www.amazon.co.uk/dp/1036969312','/books/between-the-avalanche-and-the-ashes.html','/images/featured-authors/dorota-chioma.webp','Memoir & Mental Health','A visual artist navigates the extremes of bipolar disorder, discovering that creativity can be both a refuge and a risk.','Between the Avalanche and the Ashes is an intimate memoir of living with bipolar disorder, navigating emotional extremes and rediscovering oneself through creativity.

Through personal reflections, diary entries and artistic milestones, Dorota Chioma takes readers through the exhilarating intensity of mania, the devastating weight of depression and the uncertain territory between them.

Art becomes a central thread throughout her journey — sometimes a sanctuary, sometimes an expression of overwhelming energy, and sometimes the only language available when words fail.

Rather than presenting recovery as a straightforward journey, the book explores its complexity, contradictions and fragile moments of hope. It raises difficult questions about identity, creativity, illness and the cost of pursuing passion while protecting one’s wellbeing.

Ultimately, it is a testament to the courage of continuing, creating and finding meaning in the aftermath.','archive','0' WHERE NOT EXISTS (SELECT 1 FROM pbh_books WHERE lower(title)=lower('Between the Avalanche and the Ashes'));
UPDATE pbh_books SET title='Meditation Time: Know Yourself and the World Around You', author='Laurent Grenier', genres='["Nonfiction"]', image='/images/latest/meditation-time.webp', amazon='https://www.amazon.com/Meditation-Time-Yourself-World-Around/dp/B0FV2JLC3S', feature='/books/meditation-time.html', photo='/images/featured-authors/laurent-grenier.webp', tag='Philosophical Essay', hook='A lifetime of reflection turns one life-changing question into a thoughtful guide to self-understanding and the world around us.', description='Born from the crucible of profound personal adversity, Meditation Time: Know Yourself and the World Around You is a deeply moving philosophical exploration of existence, resilience, and the art of living. At age seventeen, a catastrophic diving accident left Canadian author Laurent Grenier quadriplegic, stripping away the physical freedom of his youth and confronting him with life’s most urgent existential question: Why live?

Over four decades of rigorous contemplation, Grenier transformed that question into a luminous guide for navigating the human condition. Rather than offering quick fixes or rigid self-help formulas, this collection of concise, interconnected essays invites readers to slow down, reflect, and examine reality with clarity and honesty. Drawing from philosophy, science, and lived experience, Grenier bridges the inner landscape of self-awareness with the vast interconnectedness of the external world. He challenges conventional illusions of control, showing instead how genuine wisdom, agency, and contentment emerge when we align our thoughts with reality rather than fighting against it.

Designed to be savored and studied rather than rushed, Meditation Time serves as both a mirror and a compass. Grenier’s remarkable journey from despair to hard-won enlightenment stands as living proof that even when external circumstances narrow our physical boundaries, the mind remains vast. Ultimately, this book is a compelling invitation to awaken to the present, deepen your self-understanding, and discover enduring meaning in simply being alive.', status='archive', sort_index='0' WHERE lower(title)=lower('Meditation Time: Know Yourself and the World Around You');
INSERT INTO pbh_books(id,title,author,genres,image,amazon,feature,photo,tag,hook,description,status,sort_index) SELECT 'seed-meditation-laurent','Meditation Time: Know Yourself and the World Around You','Laurent Grenier','"[\"Nonfiction\"]"','/images/latest/meditation-time.webp','https://www.amazon.com/Meditation-Time-Yourself-World-Around/dp/B0FV2JLC3S','/books/meditation-time.html','/images/featured-authors/laurent-grenier.webp','Philosophical Essay','A lifetime of reflection turns one life-changing question into a thoughtful guide to self-understanding and the world around us.','Born from the crucible of profound personal adversity, Meditation Time: Know Yourself and the World Around You is a deeply moving philosophical exploration of existence, resilience, and the art of living. At age seventeen, a catastrophic diving accident left Canadian author Laurent Grenier quadriplegic, stripping away the physical freedom of his youth and confronting him with life’s most urgent existential question: Why live?

Over four decades of rigorous contemplation, Grenier transformed that question into a luminous guide for navigating the human condition. Rather than offering quick fixes or rigid self-help formulas, this collection of concise, interconnected essays invites readers to slow down, reflect, and examine reality with clarity and honesty. Drawing from philosophy, science, and lived experience, Grenier bridges the inner landscape of self-awareness with the vast interconnectedness of the external world. He challenges conventional illusions of control, showing instead how genuine wisdom, agency, and contentment emerge when we align our thoughts with reality rather than fighting against it.

Designed to be savored and studied rather than rushed, Meditation Time serves as both a mirror and a compass. Grenier’s remarkable journey from despair to hard-won enlightenment stands as living proof that even when external circumstances narrow our physical boundaries, the mind remains vast. Ultimately, this book is a compelling invitation to awaken to the present, deepen your self-understanding, and discover enduring meaning in simply being alive.','archive','0' WHERE NOT EXISTS (SELECT 1 FROM pbh_books WHERE lower(title)=lower('Meditation Time: Know Yourself and the World Around You'));
UPDATE pbh_authors SET name='Steven Harrison', bio='Steven Harrison is a British crime thriller author and the creator of the Sam Rourke Thriller Series. He began his working life building PCs and spent his career in IT, solving problems and teaching himself whatever the next shift in technology demanded. That habit of following clues and questioning easy answers now shapes his fiction. His debut novel, Harbinger: The Prophet’s Game, introduces a military-trained detective whose pursuit of a serial killer exposes the people and institutions that protect Chicago’s powerful. Steven publishes independently through his imprint, Steven Harrison Creative.', books='["Harbinger: The Prophet''s Game"]', photo='/images/featured-authors/steven-harrison.webp', feature='/books/harbinger-the-prophets-game.html', genres='["Mystery & Thriller"]', status='published' WHERE lower(name)=lower('Steven Harrison');
INSERT INTO pbh_authors(id,name,bio,books,photo,feature,genres,status) SELECT 'seed-author-steven','Steven Harrison','Steven Harrison is a British crime thriller author and the creator of the Sam Rourke Thriller Series. He began his working life building PCs and spent his career in IT, solving problems and teaching himself whatever the next shift in technology demanded. That habit of following clues and questioning easy answers now shapes his fiction. His debut novel, Harbinger: The Prophet’s Game, introduces a military-trained detective whose pursuit of a serial killer exposes the people and institutions that protect Chicago’s powerful. Steven publishes independently through his imprint, Steven Harrison Creative.','["Harbinger: The Prophet''s Game"]','/images/featured-authors/steven-harrison.webp','/books/harbinger-the-prophets-game.html','["Mystery & Thriller"]','published' WHERE NOT EXISTS (SELECT 1 FROM pbh_authors WHERE lower(name)=lower('Steven Harrison'));
UPDATE pbh_authors SET name='Suzanne Dana', bio='Suzanne Dana is both a general’s daughter and a general’s wife. She graduated from San Diego State University with a degree in journalism and a secondary education credential in English. As a general’s wife, she moved nineteen times and supported her husband through eight deployments, including those to Iraq and Afghanistan. She formerly sat on the Marine Corps Scholarship Foundation board as an Adjunct Director. She enjoys photography, travel, water sports, and volunteering at a local women’s shelter. She resides in Arizona with her husband. The General’s Wife is her debut novel.', books='["The General''s Wife"]', photo='/images/featured-authors/suzanne-dana.webp', feature='/books/the-generals-wife.html', genres='["Mystery & Thriller"]', status='published' WHERE lower(name)=lower('Suzanne Dana');
INSERT INTO pbh_authors(id,name,bio,books,photo,feature,genres,status) SELECT 'seed-author-suzanne','Suzanne Dana','Suzanne Dana is both a general’s daughter and a general’s wife. She graduated from San Diego State University with a degree in journalism and a secondary education credential in English. As a general’s wife, she moved nineteen times and supported her husband through eight deployments, including those to Iraq and Afghanistan. She formerly sat on the Marine Corps Scholarship Foundation board as an Adjunct Director. She enjoys photography, travel, water sports, and volunteering at a local women’s shelter. She resides in Arizona with her husband. The General’s Wife is her debut novel.','["The General''s Wife"]','/images/featured-authors/suzanne-dana.webp','/books/the-generals-wife.html','["Mystery & Thriller"]','published' WHERE NOT EXISTS (SELECT 1 FROM pbh_authors WHERE lower(name)=lower('Suzanne Dana'));
UPDATE pbh_authors SET name='Dorota Chioma', bio='Dorota Chioma is a Polish-born British-based visual artist, author and mental health advocate living with bipolar disorder. Her work explores the relationship between creativity, identity, emotional extremes and resilience. Through painting, memoir and reflective essays, she transforms lived experience into accessible conversations about mental health. Her books combine artistic expression with honest personal narratives, challenging stigma without romanticising illness or recovery. Alongside her creative practice, she works full-time. She believes that art is not merely a form of expression, but a means of survival, connection and rediscovery.', books='["Between the Avalanche and the Ashes"]', photo='/images/featured-authors/dorota-chioma.webp', feature='/books/between-the-avalanche-and-the-ashes.html', genres='["Memoir & Biography"]', status='published' WHERE lower(name)=lower('Dorota Chioma');
INSERT INTO pbh_authors(id,name,bio,books,photo,feature,genres,status) SELECT 'seed-author-dorota','Dorota Chioma','Dorota Chioma is a Polish-born British-based visual artist, author and mental health advocate living with bipolar disorder. Her work explores the relationship between creativity, identity, emotional extremes and resilience. Through painting, memoir and reflective essays, she transforms lived experience into accessible conversations about mental health. Her books combine artistic expression with honest personal narratives, challenging stigma without romanticising illness or recovery. Alongside her creative practice, she works full-time. She believes that art is not merely a form of expression, but a means of survival, connection and rediscovery.','["Between the Avalanche and the Ashes"]','/images/featured-authors/dorota-chioma.webp','/books/between-the-avalanche-and-the-ashes.html','["Memoir & Biography"]','published' WHERE NOT EXISTS (SELECT 1 FROM pbh_authors WHERE lower(name)=lower('Dorota Chioma'));
UPDATE pbh_authors SET name='Laurent Grenier', bio='Laurent Grenier is a philosopher born in France in 1957 to French Canadian parents and raised in Canada. In 1974, as he had grown into an athletic teenager, he suffered a physically disabling neck injury in a diving accident that shattered his dreams of an athletic career. Thereafter, Laurent Grenier dedicated himself to decades of meditation and study, in an effort to develop an art of living and a vision of things that make the world understandable and habitable.', books='["Meditation Time: Know Yourself and the World Around You"]', photo='/images/featured-authors/laurent-grenier.webp', feature='/books/meditation-time.html', genres='["Nonfiction"]', status='published' WHERE lower(name)=lower('Laurent Grenier');
INSERT INTO pbh_authors(id,name,bio,books,photo,feature,genres,status) SELECT 'seed-author-laurent','Laurent Grenier','Laurent Grenier is a philosopher born in France in 1957 to French Canadian parents and raised in Canada. In 1974, as he had grown into an athletic teenager, he suffered a physically disabling neck injury in a diving accident that shattered his dreams of an athletic career. Thereafter, Laurent Grenier dedicated himself to decades of meditation and study, in an effort to develop an art of living and a vision of things that make the world understandable and habitable.','["Meditation Time: Know Yourself and the World Around You"]','/images/featured-authors/laurent-grenier.webp','/books/meditation-time.html','["Nonfiction"]','published' WHERE NOT EXISTS (SELECT 1 FROM pbh_authors WHERE lower(name)=lower('Laurent Grenier'));
